import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import { signal } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { ValueTable } from '@kerfjs/ui/value-table';

const records = { alpha: { name: 'Launch plan', owner: 'Mara Chen', status: 'In review' }, beta: { name: 'Accessibility audit', owner: 'Inez Okafor', status: 'Ready' } };
export function createProjectDetailsDialog() {
  const selected = signal<keyof typeof records>('alpha');
  const open = signal(false);
  const render = () => <><button type="button" data-action="open-details">Open project details</button><wa-dialog label="Project details" open={open.value} without-header><DialogHeader title="Project details" titleId="project-details-title" summary="Compare project status without leaving the workspace." summaryId="project-details-summary" actions={<button type="button" data-action="close-details">Close</button>} /><div class="project-details kui-dialog-body"><nav class="project-details__list kui-sidebar kui-pane-body" aria-label="Projects"><MenuHeader label="Recent projects" />{Object.entries(records).map(([id, record]) => <MenuItem action="select-project" itemId={id} label={record.name} selected={selected.value === id} multiline />)}</nav><section class="project-details__detail kui-pane-body" aria-live="polite"><h3>{records[selected.value].name}</h3><ValueTable label="Project metadata"><div><dt>Owner</dt><dd>{records[selected.value].owner}</dd></div><div><dt>Status</dt><dd>{records[selected.value].status}</dd></div></ValueTable><div class="kui-control-cluster"><button type="button" data-action="archive">Archive</button><button type="button" data-action="open-project">Open project</button></div></section></div></wa-dialog></>;
  return { render, action(command: string, element: HTMLElement) { if (command === 'open-details') open.value = true; if (command === 'close-details') open.value = false; if (command === 'select-project' && element.dataset.itemId in records) selected.value = element.dataset.itemId as keyof typeof records; } };
}
